import { defineComponent, ref } from 'vue';
import cache from 'src/utils/cache';
import { getUserBasedKey } from 'src/utils/cacheHelper';
import { columnResizeKey } from 'src/constants'

type UserDetails = {
  id: string;
};

// Store per-instance data using WeakMap
const instanceData = new WeakMap<any, {
  pageX: any;
  curCol: HTMLElement | undefined;
  nxtCol: HTMLElement | undefined;
  curColWidth: any;
  nxtColWidth: any;
  dragableDivs: HTMLElement[];
  mouseUpHandler: ((e: any) => void) | null;
  mouseMoveHandler: ((e: any) => void) | null;
}>();

export default defineComponent({
  mixins: [cache],
  data() {
    return {
      allowColumSorting: ref(true),
      columnResizeKey
    }
  },
  created() {
    // Initialize instance-specific data
    instanceData.set(this, {
      pageX: undefined,
      curCol: undefined,
      nxtCol: undefined,
      curColWidth: undefined,
      nxtColWidth: undefined,
      dragableDivs: [],
      mouseUpHandler: null,
      mouseMoveHandler: null
    });
  },
  methods: {
    getInstanceData() {
      let data = instanceData.get(this);
      if (!data) {
        // Initialize if not exists (safety fallback)
        data = {
          pageX: undefined,
          curCol: undefined,
          nxtCol: undefined,
          curColWidth: undefined,
          nxtColWidth: undefined,
          dragableDivs: [],
          mouseUpHandler: null,
          mouseMoveHandler: null
        };
        instanceData.set(this, data);
      }
      return data;
    },

    initTableColumnResize(tableId: string) {
      setTimeout(() => {
        const selector = '#' + tableId;
        const tableParent = document.querySelector(selector);
        if(!tableParent) {
          return;
        }
        const tableElem : HTMLElement = tableParent.querySelector('table')!;
        if(!tableElem) {
          return;
        }
        this.resizableGrid(tableElem, tableId);
      }, 1000);
    },

    resizableGrid(table : HTMLElement, tableId: string) {
      const data = this.getInstanceData();
      const row = table.getElementsByTagName('tr')[0];
      const cols : HTMLCollection | undefined = row ? row.children : undefined;
      if (!cols) return;

      const tableHeight = table.offsetHeight;

      for (let i = 0; i < cols.length - 1; i++) {
        const dragableDiv = this.createDiv(tableHeight);
        data.dragableDivs.push(dragableDiv);
        cols[i].appendChild(dragableDiv);
        (cols[i] as HTMLElement).style.position = 'relative';
        this.setListeners(dragableDiv, tableId);
      }
    },

    setListeners(dragableDiv: HTMLElement, tableId: string){
      const data = this.getInstanceData();

      // Create bound handlers specific to this dragableDiv
      const mousedownHandler = (e: any) => this.mousedownListener(e);
      dragableDiv.addEventListener('mousedown', mousedownHandler);

      dragableDiv.addEventListener('mouseover', function (e : any) {
        e.target.classList.toggle('active-border-right-2px');
      })

      dragableDiv.addEventListener('mouseout', function (e : any) {
        e.target.classList.toggle('active-border-right-2px');
      })

      // Create instance-specific mouseup handler if not exists
      if (!data.mouseUpHandler) {
        data.mouseUpHandler = (e: any) => {
          if (data.curCol) {
            this.mouseUpListener(e, tableId);
          }
        };
        document.addEventListener('mouseup', data.mouseUpHandler);
      }
    },
    createDiv(height : number){
      const div: HTMLElement = document.createElement('div');
      div.style.top = '0';
      div.style.right = '0';
      div.style.width = '5px';
      div.style.position = 'absolute';
      div.style.cursor = 'col-resize';
      div.style.userSelect = 'none';
      div.style.height = height + 'px';
      return div;
    },

    paddingDiff(col: HTMLElement){

      if (this.getStyleVal(col,'box-sizing') == 'border-box') {
        return 0;
      }

      const padLeft = this.getStyleVal(col,'padding-left');
      const padRight = this.getStyleVal(col,'padding-right');
      return (parseInt(padLeft) + parseInt(padRight));
    },

    getStyleVal(elm : HTMLElement,css : string) {
      return (window.getComputedStyle(elm, null).getPropertyValue(css));
    },

    mousedownListener(e : any) {
      const data = this.getInstanceData();

      this.allowColumSorting = false;
      data.curCol = e.target.parentElement;
      data.nxtCol = (data.curCol!.nextElementSibling as HTMLElement);
      data.pageX = e.pageX;

      if(data.curCol && data.nxtCol && data.pageX) {

        const padding = this.paddingDiff(data.curCol);

        data.curColWidth = data.curCol.offsetWidth - padding;
        if (data.nxtCol) {
          data.nxtColWidth = data.nxtCol.offsetWidth - padding;
        }

        // Create instance-specific mousemove handler if not exists
        if (!data.mouseMoveHandler) {
          data.mouseMoveHandler = (e: any) => this.mouseMoveListener(e);
        }
        document.addEventListener('mousemove', data.mouseMoveHandler);
      }
    },
    mouseMoveListener(e : any) {
      const data = this.getInstanceData();

      if (data.curCol) {
        const diffX = e.pageX - data.pageX;

          if (data.nxtCol && diffX > 0) {
            data.nxtCol.style.width = (data.nxtColWidth - (diffX))+'px';
            data.nxtCol.style.minWidth = (data.nxtColWidth - (diffX))+'px';
          }

          data.curCol.style.width = (data.curColWidth + diffX)+'px';
          data.curCol.style.minWidth = (data.curColWidth + diffX)+'px';
        }
    },
    mouseUpListener(e : any, tableId: string) {
      const data = this.getInstanceData();

      this.allowColumSorting = true;

      // Remove mousemove listener
      if (data.mouseMoveHandler) {
        document.removeEventListener('mousemove', data.mouseMoveHandler);
      }

      //Get column size updates and save them in cookies
      const targetTable = (e.target as HTMLElement).closest('.q-table')
      if( !targetTable ) {
        this.clearVariables();
        return;
      }
      const headers = targetTable.querySelectorAll('th');
      const widths: number[] = [];
      headers.forEach((th: any) => {
        widths.push(th.offsetWidth);
      });
      this.setDataToLocalStorage(getUserBasedKey(tableId + '_' + this.columnResizeKey), JSON.stringify(widths));

      this.clearVariables();
    },
    clearVariables() {
      const data = this.getInstanceData();
      data.pageX = undefined;
      data.curCol = undefined;
      data.nxtCol = undefined;
      data.nxtColWidth = undefined;
      data.curColWidth = undefined;
    },

    destoryAndRest(tableId: string) {
      const data = this.getInstanceData();

      if(!data || !data.dragableDivs || data.dragableDivs.length == 0) {
        return;
      }

      // Remove all draggable divs
      data.dragableDivs.forEach((div: HTMLElement) => {
        if (div && div.parentElement) {
          div.parentElement.removeChild(div);
        }
      });
      data.dragableDivs.length = 0; // Clear the array

      // Remove document-wide listeners
      if (data.mouseUpHandler) {
        document.removeEventListener('mouseup', data.mouseUpHandler);
        data.mouseUpHandler = null;
      }

      if (data.mouseMoveHandler) {
        document.removeEventListener('mousemove', data.mouseMoveHandler);
        data.mouseMoveHandler = null;
      }

      // Clear variables
      data.pageX = undefined;
      data.curCol = undefined;
      data.nxtCol = undefined;
      data.nxtColWidth = undefined;
      data.curColWidth = undefined;

      // Reset any other column settings if necessary
      this.allowColumSorting = true;
    },
    resetAndReInitColumnResize(tableId: string) {
      this.destoryAndRest(tableId);
      this.initTableColumnResize(tableId);
    },
    restoreSavedColumnWidths(table: HTMLElement, tableId: string) {
      //Get column size from cookies and set to columns
      const columnWidths = JSON.parse(this.getDataByKey(getUserBasedKey(tableId + '_' + this.columnResizeKey)) as string)
      if ( !columnWidths ) {
        return;
      }
      const headers = table.querySelectorAll('th');
      headers.forEach((th, index) => {
        if ( !columnWidths[index] ) {
          return;
        }
        const el = th as HTMLElement;
        el.style.width = columnWidths[index] + 'px';
        el.style.minWidth = columnWidths[index] + 'px';
      });
    }
  }
});
